Funcion pesos <- PriceInPesos(dollars Como Entero, rate Como Entero)
  Definir pesos Como Entero;
  pesos <- dollars * rate;
FinFuncion

Algoritmo Price
  Definir dollars Como Entero;
  Definir rate Como Entero;
  Leer dollars;
  Leer rate;
  Escribir PriceInPesos(dollars, rate);
FinAlgoritmo
